    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    # Full divider rows and columns are the panel boundaries.
    hr = [r for r, row in enumerate(g) if len(set(row)) == 1 and row[0] != 0]
    vc = [c for c in range(w) if len({g[r][c] for r in range(h)}) == 1 and g[0][c] != 0]
    # Keep only separators matching the task's repeated grid structure.
    r_bounds = [-1] + hr + [h]
    c_bounds = [-1] + vc + [w]
    panels = {}
    for i in range(len(r_bounds)-1):
        for j in range(len(c_bounds)-1):
            r0, r1 = r_bounds[i]+1, r_bounds[i+1]
            c0, c1 = c_bounds[j]+1, c_bounds[j+1]
            panels[i,j] = [row[c0:c1] for row in g[r0:r1]]
    def flipud(a): return a[::-1]
    def fliplr(a): return [row[::-1] for row in a]
    def nonempty(a): return any(v for row in a for v in row)
    def same(a,b): return a == b
    # A boundary is a mirror axis when at least one adjacent panel pair already
    # exhibits that exact reflection. Complete the reflection along that axis.
    horizontal_axes = set()
    for i in range(len(r_bounds)-2):
        for j in range(len(c_bounds)-1):
            a,b = panels[i,j], panels[i+1,j]
            if len(a)==len(b) and len(a[0])==len(b[0]) and nonempty(a) and same(flipud(a),b):
                horizontal_axes.add(i)
    vertical_axes = set()
    for j in range(len(c_bounds)-2):
        for i in range(len(r_bounds)-1):
            a,b = panels[i,j], panels[i,j+1]
            if len(a)==len(b) and len(a[0])==len(b[0]) and nonempty(a) and same(fliplr(a),b):
                vertical_axes.add(j)
    def fill_pair(a,b,reflect):
        if nonempty(a) and not nonempty(b):
            return a, reflect(a)
        if nonempty(b) and not nonempty(a):
            return reflect(b), b
        return a,b
    for i in horizontal_axes:
        for j in range(len(c_bounds)-1):
            a,b=panels[i,j],panels[i+1,j]
            a,b=fill_pair(a,b,flipud)
            panels[i,j],panels[i+1,j]=a,b
    for j in vertical_axes:
        for i in range(len(r_bounds)-1):
            a,b=panels[i,j],panels[i,j+1]
            a,b=fill_pair(a,b,fliplr)
            panels[i,j],panels[i,j+1]=a,b
    for (i,j),a in panels.items():
        r0,c0=r_bounds[i]+1,c_bounds[j]+1
        for y,row in enumerate(a):
            for x,v in enumerate(row):
                if g[r0+y][c0+x] == 0:
                    g[r0+y][c0+x]=v
    return g
'''
